#!/usr/bin/env python3
"""
Build context-heavy prompt sets for abliteration activation capture.

Prepends a ~50-75k token context prefix (system prompt + tool defs + 50 realistic
multi-turn conversation exchanges) to each prompt in the refusal/safety/benign sets.

The context prefix is IDENTICAL across all three sets so the only variable is the
final user question.

Output: prompts_{refusal,safety,benign}_ctx.json
Each file contains a list of conversation objects (list of role/content dicts).

Usage:
  python build_context_prompts.py [--estimate-only]
"""

import json
import argparse
from pathlib import Path

